window.HEROES = [{"id": 1, "name": "宋江", "nick": "呼保义", "bio": "原在郓城县做押司，江湖上又称他为“及时雨”。他结识了许多伙伴，后来成为梁山首领，负责统领众人。", "cue": "蓝帽、卷轴、小胡须", "group": 0}, {"id": 2, "name": "卢俊义", "nick": "玉麒麟", "bio": "大名府的员外，棍棒功夫出众。经历波折后加入梁山，座次仅次于宋江，与他一同统领山寨。", "cue": "玉色铠甲、金冠、长棍", "group": 0}, {"id": 3, "name": "吴用", "nick": "智多星", "bio": "原是一位教书先生，善于观察和谋划。他参与智取生辰纲，后来担任梁山军师，为众人出主意。", "cue": "方帽、羽扇、竹简", "group": 0}, {"id": 4, "name": "公孙胜", "nick": "入云龙", "bio": "道号一清的道士，与晁盖等人结识。在小说的奇幻世界里，他会运用道术，也是梁山军师之一。", "cue": "青绿道袍、拂尘", "group": 0}, {"id": 5, "name": "关胜", "nick": "大刀", "bio": "原是武官，擅长使用大刀。来到梁山后成为马军五虎将之一，长髯与大刀是他的鲜明标志。", "cue": "绿袍、长髯、大刀", "group": 0}, {"id": 6, "name": "林冲", "nick": "豹子头", "bio": "原是禁军教头，熟悉枪棒。他遭到陷害，经历风雪山神庙等波折后上梁山，成为马军五虎将之一。", "cue": "蓝衣、红缨枪", "group": 0}, {"id": 7, "name": "秦明", "nick": "霹雳火", "bio": "原是青州武官，性情急躁，声音洪亮，善用狼牙棒。加入梁山后，他列入马军五虎将。", "cue": "赤色铠甲、狼牙棒", "group": 0}, {"id": 8, "name": "呼延灼", "nick": "双鞭", "bio": "原是汝宁州武官，善使两条钢鞭。他曾率连环马作战，后来加入梁山，列入马军五虎将。", "cue": "藏蓝铠甲、两条硬鞭", "group": 0}, {"id": 9, "name": "花荣", "nick": "小李广", "bio": "原在清风寨任武职，与宋江交好。他的弓箭本领很高，因此得到“小李广”的绰号。", "cue": "白绿衣袍、弓箭", "group": 0}, {"id": 10, "name": "柴进", "nick": "小旋风", "bio": "出身贵族，喜欢结交江湖人物，曾接待林冲、武松等人。来到梁山后，他与李应共同掌管钱粮。", "cue": "金色长袍、小礼盒", "group": 0}, {"id": 11, "name": "李应", "nick": "扑天雕", "bio": "原是李家庄庄主，与祝家庄、扈家庄相邻。他武艺出众，上梁山后与柴进一同管理钱粮。", "cue": "鹰纹衣袍、账卷、钥匙", "group": 0}, {"id": 12, "name": "朱仝", "nick": "美髯公", "bio": "原是郓城县都头，留着一副漂亮长髯。他曾帮助宋江等人脱困，后来成为梁山的马军头领。", "cue": "长长的胡须、紫褐衣袍", "group": 0}, {"id": 13, "name": "鲁智深", "nick": "花和尚", "bio": "原名鲁达，做过提辖，后来出家。他曾帮助金氏父女，也在野猪林救过林冲，是个见不得不平事的人。", "cue": "光头、念珠、禅杖", "group": 1}, {"id": 14, "name": "武松", "nick": "行者", "bio": "在景阳冈打虎的故事中出场，后来做过阳谷县都头。经历许多波折后，他以行者装束行走江湖。", "cue": "头箍、念珠、双刀", "group": 1}, {"id": 15, "name": "董平", "nick": "双枪将", "bio": "原是东平府武官，善于同时使用两支长枪。来到梁山后，他成为马军五虎将之一。", "cue": "绿色铠甲、两支枪", "group": 1}, {"id": 16, "name": "张清", "nick": "没羽箭", "bio": "原是东昌府武官，擅长投掷石子。他与梁山交战时展现本领，后来和龚旺、丁得孙一同入伙。", "cue": "蓝头巾、圆石子", "group": 1}, {"id": 17, "name": "杨志", "nick": "青面兽", "bio": "脸上有一块青色胎记，曾担任殿帅府制使。他押送生辰纲失利后辗转江湖，后来从二龙山来到梁山。", "cue": "脸侧青记、蓝褐衣袍", "group": 1}, {"id": 18, "name": "徐宁", "nick": "金枪手", "bio": "原是禁军金枪班教头，擅长钩镰枪。来到梁山后，他传授枪法，帮助众人破解连环马。", "cue": "金色铠甲、钩镰枪", "group": 1}, {"id": 19, "name": "索超", "nick": "急先锋", "bio": "原在大名府军中任职，惯使大斧。因为上阵时急于冲在前面，所以被叫作“急先锋”。", "cue": "铜色铠甲、大斧", "group": 1}, {"id": 20, "name": "戴宗", "nick": "神行太保", "bio": "原在江州当差。小说写他会神行术，能快速赶路；到梁山后，他负责探听消息、联络伙伴。", "cue": "绿衣、绑腿、红挎包", "group": 1}, {"id": 21, "name": "刘唐", "nick": "赤发鬼", "bio": "因赤色鬓发而有了绰号，曾把生辰纲的消息带给晁盖。他是早期参与聚义的人物，后来担任步军头领。", "cue": "赤色鬓发、棕红短衣", "group": 1}, {"id": 22, "name": "李逵", "nick": "黑旋风", "bio": "人称“铁牛”，使一对板斧，后来成为梁山步军头领。他力气大、性子急，常因冲动惹出麻烦。", "cue": "黑须、黑衣、双板斧", "group": 1}, {"id": 23, "name": "史进", "nick": "九纹龙", "bio": "史家庄的青年，曾向教头王进学习武艺。身上的九龙纹饰使他得到绰号，也是全书很早出场的人物。", "cue": "龙纹衣袍、长棍", "group": 1}, {"id": 24, "name": "穆弘", "nick": "没遮拦", "bio": "原住揭阳镇，是穆春的哥哥。与宋江结识后加入梁山，担任马军头领，并与李逵守把北山关。", "cue": "紫色长衣、蓝腰带", "group": 1}, {"id": 25, "name": "雷横", "nick": "插翅虎", "bio": "原是郓城县步兵都头，与朱仝相熟。身手矫健，后来上梁山担任步军头领，也负责守关。", "cue": "红头巾、轻巧身姿", "group": 2}, {"id": 26, "name": "李俊", "nick": "混江龙", "bio": "熟悉江河水路，曾在危难中帮助宋江。加入梁山后，他成为水军头领，与伙伴们一同管理水寨。", "cue": "青蓝短衣、木桨", "group": 2}, {"id": 27, "name": "阮小二", "nick": "立地太岁", "bio": "阮氏三兄弟中的老大，原在石碣村捕鱼。他参加智取生辰纲，后来成为梁山水军头领。", "cue": "方胡须、渔绳", "group": 2}, {"id": 28, "name": "张横", "nick": "船火儿", "bio": "张顺的哥哥，熟悉撑船和水上活动。后来成为梁山水军头领，与弟弟一起守西南水寨。", "cue": "红头巾、深蓝衣、船桨", "group": 2}, {"id": 29, "name": "阮小五", "nick": "短命二郎", "bio": "阮氏三兄弟中的老二，原是石碣村渔民。上梁山后掌管水军，与童威一同守东北水寨。", "cue": "绿短衣、鱼篓", "group": 2}, {"id": 30, "name": "张顺", "nick": "浪里白条", "bio": "张横的弟弟，水性出众，能在水中灵活行动。他加入梁山水军，还曾参与请安道全上山的故事。", "cue": "白蓝衣衫、水上浮圈", "group": 2}, {"id": 31, "name": "阮小七", "nick": "活阎罗", "bio": "阮氏三兄弟中最小的一位，性情直爽。参加早期聚义后成为水军头领，与童猛守西北水寨。", "cue": "橙色短衣、爽朗笑容", "group": 2}, {"id": 32, "name": "杨雄", "nick": "病关索", "bio": "原在蓟州当差，与石秀结为兄弟。经历波折后两人投奔梁山，他后来担任步军头领、守把西山关。", "cue": "紫色衣衫、红腰带", "group": 2}, {"id": 33, "name": "石秀", "nick": "拼命三郎", "bio": "曾以卖柴为生，与杨雄相识。卢俊义遇险时，他冒险前去相救；后来成为梁山步军头领。", "cue": "布帽、柴束、短棍", "group": 2}, {"id": 34, "name": "解珍", "nick": "两头蛇", "bio": "登州猎户，是解宝的哥哥。兄弟俩打虎后遭到陷害，获亲友相助脱困，后来一同来到梁山。", "cue": "绿猎帽、叉形猎杖", "group": 2}, {"id": 35, "name": "解宝", "nick": "双尾蝎", "bio": "解珍的弟弟，也是一名猎户。两人共同经历登州风波，加入梁山后一起守把山前第一关。", "cue": "黄猎帽、弓箭", "group": 2}, {"id": 36, "name": "燕青", "nick": "浪子", "bio": "人称“燕小乙”，原在卢俊义家中生活。他聪明灵巧，会相扑，也懂吹拉弹唱，是多才多艺的人物。", "cue": "浅绿衣袍、竹笛", "group": 2}, {"id": 37, "name": "朱武", "nick": "神机军师", "bio": "原是少华山头领之一，熟悉阵法。来到梁山后，他协助吴用等人参赞军务，负责出谋划策。", "cue": "紫色书生衣、地图", "group": 3}, {"id": 38, "name": "黄信", "nick": "镇三山", "bio": "原在青州任职，与秦明关系密切。他因夸称能镇住三座山而得绰号，后来在梁山担任马军头领。", "cue": "山纹铠甲、腰刀", "group": 3}, {"id": 39, "name": "孙立", "nick": "病尉迟", "bio": "原是登州提辖，孙新的哥哥。他参加营救解氏兄弟的行动，后来在祝家庄故事中发挥重要作用。", "cue": "黑金铠甲、单条硬鞭", "group": 3}, {"id": 40, "name": "宣赞", "nick": "丑郡马", "bio": "原是武官，曾与关胜、郝思文一起出征。上梁山后担任马军头领；他的故事也提醒人别只凭相貌判断别人。", "cue": "宽脸、浓眉、红褐甲", "group": 3}, {"id": 41, "name": "郝思文", "nick": "井木犴", "bio": "与关胜交好，曾同关胜、宣赞一起行动。加入梁山后，他成为马军头领，也担任远探出哨的任务。", "cue": "蓝盔、青色铠甲、长枪", "group": 3}, {"id": 42, "name": "韩滔", "nick": "百胜将", "bio": "原是陈州团练使，曾在呼延灼军中任先锋。后来加入梁山，成为马军小彪将，承担侦察等事务。", "cue": "黄褐铠甲、长柄棍", "group": 3}, {"id": 43, "name": "彭玘", "nick": "天目将", "bio": "原是颍州团练使，与韩滔同在呼延灼军中。上梁山后，他担任马军头领，驻守正北旱寨。", "cue": "红紫铠甲、长柄戟", "group": 3}, {"id": 44, "name": "单廷珪", "nick": "圣水将", "bio": "原在凌州任团练使，与魏定国一同出场。小说写他擅长用水作战，后来加入梁山马军。", "cue": "蓝色水纹、蓝小旗", "group": 3}, {"id": 45, "name": "魏定国", "nick": "神火将", "bio": "原是凌州团练使，与单廷珪并肩作战。小说写他擅长火攻；到梁山后，他也是马军头领之一。", "cue": "红色火纹、红小旗", "group": 3}, {"id": 46, "name": "萧让", "nick": "圣手书生", "bio": "是一位擅长书法的文人，能写多种书体。上梁山后，他负责起草文书、传达命令，是队伍里的笔墨能手。", "cue": "毛笔、书卷、绿长袍", "group": 3}, {"id": 47, "name": "裴宣", "nick": "铁面孔目", "bio": "原是掌管文书事务的孔目，后来到饮马川。加入梁山后，他负责考核功过和赏罚，重视规矩。", "cue": "深蓝官帽、卷册、木尺", "group": 3}, {"id": 48, "name": "欧鹏", "nick": "摩云金翅", "bio": "原是黄门山头领之一，与蒋敬、马麟、陶宗旺结伴。上梁山后担任马军头领，驻守正南旱寨。", "cue": "蓝灰披风、长枪", "group": 3}, {"id": 49, "name": "邓飞", "nick": "火眼狻猊", "bio": "原在饮马川与裴宣、孟康结伴，善用铁链。后来加入梁山，担任马军头领，也参加远探出哨。", "cue": "红眼缘、盘起的链条", "group": 4}, {"id": 50, "name": "燕顺", "nick": "锦毛虎", "bio": "原是清风山头领之一，与王英、郑天寿同在山中。结识宋江后，他辗转来到梁山，担任马军头领。", "cue": "赤色胡须、虎纹披肩", "group": 4}, {"id": 51, "name": "杨林", "nick": "锦豹子", "bio": "是一位行走江湖的人物，曾与戴宗结伴。上梁山后，他成为马军头领，也承担探查消息的任务。", "cue": "蓝头巾、豹点腰巾", "group": 4}, {"id": 52, "name": "凌振", "nick": "轰天雷", "bio": "原是军中炮手，擅长制造和使用火炮。上梁山后，他负责制造号炮；本册用小模型表现他的工艺本领。", "cue": "工匠围裙、小炮模型", "group": 4}, {"id": 53, "name": "蒋敬", "nick": "神算子", "bio": "原是黄门山伙伴之一，精于计算。上梁山后，他核算钱粮的收入与支出，让各项账目清楚明白。", "cue": "算盘、账本、黄长袍", "group": 4}, {"id": 54, "name": "吕方", "nick": "小温侯", "bio": "曾在对影山活动，因喜爱吕布的形象而得绰号。他善用画戟，后来与郭盛一同守护中军。", "cue": "红甲、红缨、画戟", "group": 4}, {"id": 55, "name": "郭盛", "nick": "赛仁贵", "bio": "擅长使用画戟，曾与吕方比试，两人的兵器缠在一起。上梁山后，他和吕方一起担任护卫。", "cue": "白甲、白缨、画戟", "group": 4}, {"id": 56, "name": "安道全", "nick": "神医", "bio": "是一位医术高明的大夫，家住建康府。梁山请他上山为宋江治病，后来由他负责医治众人的疾病。", "cue": "药箱、草药包", "group": 4}, {"id": 57, "name": "皇甫端", "nick": "紫髯伯", "bio": "因紫色胡须而有了绰号，是一位善于医马的兽医。来到梁山后，负责照顾和医治马匹。", "cue": "紫褐胡须、兽医包", "group": 4}, {"id": 58, "name": "王英", "nick": "矮脚虎", "bio": "身材矮小，原是清风山头领之一。上梁山后，他与扈三娘负责军中探察；两人也是小说中的夫妻。", "cue": "矮壮身形、虎纹短衣", "group": 4}, {"id": 59, "name": "扈三娘", "nick": "一丈青", "bio": "扈家庄的女将，擅使日月双刀，也善用套索。她是梁山三位女头领之一，后来承担军中探察任务。", "cue": "高马尾、青白甲、双刀", "group": 4}, {"id": 60, "name": "鲍旭", "nick": "丧门神", "bio": "原在枯树山活动，与李逵结识后加入梁山。他成为步军将校，常与李逵、项充、李衮配合作战。", "cue": "浓胡须、宽大的鞘刀", "group": 4}, {"id": 61, "name": "樊瑞", "nick": "混世魔王", "bio": "原是芒砀山头领，小说写他会道术。加入梁山后，他向公孙胜学习，也成为步军将校。", "cue": "紫色道袍、拂尘", "group": 5}, {"id": 62, "name": "孔明", "nick": "毛头星", "bio": "孔亮的哥哥，曾在白虎山活动，与宋江相识。他来到梁山后守护中军；他不是《三国演义》的诸葛亮。", "cue": "红头巾、棕色短衣", "group": 5}, {"id": 63, "name": "孔亮", "nick": "独火星", "bio": "孔明的弟弟，与哥哥一起经历白虎山的故事。加入梁山后，兄弟二人共同担任中军护卫。", "cue": "蓝头巾、青绿短衣", "group": 5}, {"id": 64, "name": "项充", "nick": "八臂哪吒", "bio": "原是芒砀山伙伴之一，善使团牌和飞刀。后来担任梁山步军将校；“八臂”是绰号，他只有两只手臂。", "cue": "圆盾、橙蓝衣衫", "group": 5}, {"id": 65, "name": "李衮", "nick": "飞天大圣", "bio": "与樊瑞、项充同在芒砀山，善使团牌与标枪。上梁山后，他成为步军将校，与伙伴们相互配合。", "cue": "藤盾、木标枪", "group": 5}, {"id": 66, "name": "金大坚", "nick": "玉臂匠", "bio": "是一位擅长雕刻的工匠。上梁山后，他负责制作兵符、印信，把细致的手艺用在队伍的日常事务中。", "cue": "印章、刻工工具", "group": 5}, {"id": 67, "name": "马麟", "nick": "铁笛仙", "bio": "原在黄门山与欧鹏等人结伴，擅长吹铁笛，也会武艺。上梁山后担任马军头领，并参与远探出哨。", "cue": "铁笛、淡蓝长袍", "group": 5}, {"id": 68, "name": "童威", "nick": "出洞蛟", "bio": "童猛的哥哥，熟悉水路，与李俊交好。加入梁山后成为水军头领，与阮小五一起守东北水寨。", "cue": "青衣、盘绳", "group": 5}, {"id": 69, "name": "童猛", "nick": "翻江蜃", "bio": "童威的弟弟，也善于水上活动。上梁山后，他与阮小七共同守西北水寨，是八位水军头领之一。", "cue": "蓝衣、红头带、船桨", "group": 5}, {"id": 70, "name": "孟康", "nick": "玉幡竿", "bio": "身材高大，肤色白净，原是造船工匠。上梁山后，他负责监造战船，让木料和手艺变成水上舟楫。", "cue": "白衣围裙、小船模型", "group": 5}, {"id": 71, "name": "侯健", "nick": "通臂猿", "bio": "身手灵活，也是一位裁缝。来到梁山后，他负责制作旗帜与衣袍，是让整支队伍穿戴整齐的巧手。", "cue": "布匹、卷尺、线轴", "group": 5}, {"id": 72, "name": "陈达", "nick": "跳涧虎", "bio": "原是少华山头领之一，与朱武、杨春结伴。他曾和史进交手，后来上梁山成为马军头领。", "cue": "绿衣、红褐围巾、长枪", "group": 5}, {"id": 73, "name": "杨春", "nick": "白花蛇", "bio": "原在少华山与朱武、陈达结伴，身材高瘦，善用大刀。后来加入梁山，成为马军头领之一。", "cue": "白绿衣、细长身形", "group": 6}, {"id": 74, "name": "郑天寿", "nick": "白面郎君", "bio": "面容白净，原做过银匠，后来与燕顺、王英同在清风山。上梁山后担任步军将校。", "cue": "浅色衣衫、小银饰", "group": 6}, {"id": 75, "name": "陶宗旺", "nick": "九尾龟", "bio": "出身农家，原是黄门山伙伴之一。来到梁山后，他负责监筑城墙，参与山寨的营建。", "cue": "工匠围裙、铲子", "group": 6}, {"id": 76, "name": "宋清", "nick": "铁扇子", "bio": "宋江的弟弟，原在家乡生活。上梁山后，他负责安排筵席；聚会顺利，也需要有人照料许多细节。", "cue": "蓝衣、茶盘", "group": 6}, {"id": 77, "name": "乐和", "nick": "铁叫子", "bio": "原在登州当差，善于唱曲，也很机灵。加入梁山后，他参与传递机密消息，是联络队伍的一员。", "cue": "绿袍、小扇、歌唱姿态", "group": 6}, {"id": 78, "name": "龚旺", "nick": "花项虎", "bio": "原是张清部下，身上有虎纹，善使飞枪。他与丁得孙一起加入梁山，后来担任步军将校。", "cue": "虎纹衣领、木标枪", "group": 6}, {"id": 79, "name": "丁得孙", "nick": "中箭虎", "bio": "原是张清部下，脸颊有伤痕，善使飞叉。他与龚旺配合行动，上梁山后成为步军将校。", "cue": "面颊小疤、绿褐甲", "group": 6}, {"id": 80, "name": "穆春", "nick": "小遮拦", "bio": "穆弘的弟弟，原住揭阳镇。经历与宋江相识的故事后，他也来到梁山，担任步军将校。", "cue": "紫衣、黄腰带", "group": 6}, {"id": 81, "name": "曹正", "nick": "操刀鬼", "bio": "原做过屠户，学过林冲的武艺，也参与二龙山的故事。上梁山后，他负责牲畜屠宰等伙食供应事务。", "cue": "白头巾、围裙、食篮", "group": 6}, {"id": 82, "name": "宋万", "nick": "云里金刚", "bio": "梁山早期的头领之一，身材高大。后来山寨聚齐一百零八人，他担任步军将校。", "cue": "蓝衣、宽大身形", "group": 6}, {"id": 83, "name": "杜迁", "nick": "摸着天", "bio": "与宋万一样，是梁山早期的头领。因身材高大而有了绰号，大聚义后担任步军将校。", "cue": "高个子、举起的手掌", "group": 6}, {"id": 84, "name": "薛永", "nick": "病大虫", "bio": "以卖药、使枪棒为生，曾在揭阳镇遇到宋江。来到梁山后，他成为步军将校。", "cue": "行囊、药包、木棍", "group": 6}, {"id": 85, "name": "施恩", "nick": "金眼彪", "bio": "孟州人，曾照顾遭难的武松，也与快活林的故事有关。后来他加入梁山，担任步军将校。", "cue": "金头带、绿衣", "group": 7}, {"id": 86, "name": "李忠", "nick": "打虎将", "bio": "以使枪卖药为生，曾给史进指点武艺。他后来在桃花山活动，最后加入梁山担任步军将校。", "cue": "药囊、红头巾、长棍", "group": 7}, {"id": 87, "name": "周通", "nick": "小霸王", "bio": "原是桃花山头领，与李忠结伴，曾在桃花村遇见鲁智深。上梁山后，他成为马军头领之一。", "cue": "红头巾、短胡须", "group": 7}, {"id": 88, "name": "汤隆", "nick": "金钱豹子", "bio": "是一名铁匠，也是徐宁的表弟。上梁山后，他负责打造军器铁件；牢靠的工具离不开手艺人的细心。", "cue": "铁匠围裙、锤子、马蹄铁", "group": 7}, {"id": 89, "name": "杜兴", "nick": "鬼脸儿", "bio": "原在李应家中做管事，与李应一同来到梁山。后来他和朱贵经营南山酒店，负责接待来宾、打听消息。", "cue": "浓眉、大耳、账册", "group": 7}, {"id": 90, "name": "邹渊", "nick": "出林龙", "bio": "原在登云山活动，是邹润的叔叔。参与登州营救后，他加入梁山，担任步军将校。", "cue": "蓝衣、胡须、腰刀", "group": 7}, {"id": 91, "name": "邹润", "nick": "独角龙", "bio": "邹渊的侄子，头后有一处隆起，因此得到绰号。他与叔叔一起参加营救，后来担任梁山步军将校。", "cue": "头后小突起、绿短衣", "group": 7}, {"id": 92, "name": "朱贵", "nick": "旱地忽律", "bio": "是梁山早期人物之一，在山下酒店接应来客。大聚义后，他与杜兴一起负责南山酒店及消息联络。", "cue": "茶壶、棕衣、蓝围裙", "group": 7}, {"id": 93, "name": "朱富", "nick": "笑面虎", "bio": "朱贵的弟弟，曾经营酒店。来到梁山后，他负责酒筵供应，与安排筵席的宋清各有分工。", "cue": "圆脸笑容、围裙、食碗", "group": 7}, {"id": 94, "name": "蔡福", "nick": "铁臂膊", "bio": "原在大名府当差，是蔡庆的哥哥。卢俊义受困时，他曾参与相助，后来与弟弟一起上梁山。", "cue": "粗壮手臂、紫衣", "group": 7}, {"id": 95, "name": "蔡庆", "nick": "一枝花", "bio": "蔡福的弟弟，喜欢在头边戴一枝花。他与哥哥经历大名府的故事，后来共同成为梁山一员。", "cue": "帽边小花、青衣", "group": 7}, {"id": 96, "name": "李立", "nick": "催命判官", "bio": "原在揭阳岭开酒店，与李俊等人相识。上梁山后，他和王定六负责北山酒店，接待来客、探听消息。", "cue": "赤色胡须、木托盘", "group": 7}, {"id": 97, "name": "李云", "nick": "青眼虎", "bio": "原是沂水县都头，与朱富有师徒关系。来到梁山后，他负责建造和修缮房舍，也有营建方面的本领。", "cue": "蓝工作衣、木工尺", "group": 8}, {"id": 98, "name": "焦挺", "nick": "没面目", "bio": "出身相扑之家，擅长摔跤。他与李逵相识后加入梁山，成为步军将校，绰号并不是说他没有脸。", "cue": "结实身形、相扑架势", "group": 8}, {"id": 99, "name": "石勇", "nick": "石将军", "bio": "大名府人，行走江湖时曾为宋江带来家书。后来来到梁山，担任步军将校。", "cue": "灰衣、黄头巾、书信", "group": 8}, {"id": 100, "name": "孙新", "nick": "小尉迟", "bio": "孙立的弟弟，与顾大嫂经营酒店。他参与营救解氏兄弟，上梁山后与顾大嫂共同负责东山酒店。", "cue": "绿衣、茶壶、短胡须", "group": 8}, {"id": 101, "name": "顾大嫂", "nick": "母大虫", "bio": "孙新的妻子，也是解珍、解宝的表姐。她参与策划营救，做事果断，是梁山三位女头领之一。", "cue": "红褐衣、围裙、叉腰", "group": 8}, {"id": 102, "name": "张青", "nick": "菜园子", "bio": "曾做过园丁，后来与孙二娘经营酒店。上梁山后两人负责西山酒店；他的名字别与“张清”混淆。", "cue": "草帽、菜篮、绿衣", "group": 8}, {"id": 103, "name": "孙二娘", "nick": "母夜叉", "bio": "与张青经营酒店，在武松的故事中出场。她是梁山三位女头领之一，后来负责西山酒店的接待和联络。", "cue": "花簪、红衣、茶盘", "group": 8}, {"id": 104, "name": "王定六", "nick": "活闪婆", "bio": "原在建康府江边经营酒店，行动轻快。来到梁山后，他与李立一起负责北山酒店。", "cue": "绑腿、蓝灰衣、挎包", "group": 8}, {"id": 105, "name": "郁保四", "nick": "险道神", "bio": "身材高大，在曾头市一段故事中出场。上梁山后，他专门负责捧帅旗，让队伍看清旗号。", "cue": "高个子、杏黄旗", "group": 8}, {"id": 106, "name": "白胜", "nick": "白日鼠", "bio": "黄泥冈故事中，他扮作卖酒人，与晁盖等人配合。上梁山后，他承担传递机密消息的工作。", "cue": "白头巾、小木桶", "group": 8}, {"id": 107, "name": "时迁", "nick": "鼓上蚤", "bio": "身材轻巧，善于攀爬潜行，曾参与盗甲等情节。到梁山后负责侦察、传递消息；本册以信卷表现他的灵巧。", "cue": "轻巧蹲姿、信卷", "group": 8}, {"id": 108, "name": "段景住", "nick": "金毛犬", "bio": "因赤发黄须而得绰号，熟悉马匹，曾带来宝马的消息，引出曾头市风波。他在梁山座次中排第一百零八。", "cue": "金黄胡须、马缰、梳刷", "group": 8}];
